  幻影: '你的分身，隨機放你裝著的攻擊技能，傷害打折。',
  格擋值:
    '每面盾都有：等於盾上的護甲 ×（1 + 盾的護甲更多）（盾上的護甲 = 基底護甲 × 品質 + 護甲詞綴）。大於 0 時每一下吸收 40% 傷害；打碎後要等它跑滿才再吸收。',
