  經久技能: '一段時間內打出大量擊中，每一下各自判定暴擊（不像其他技能一次只判一次）；吃「經久傷害提高」。',
  增加技能使用時間: '額外的出手時間，固定秒數，不吃任何速度，加在出手時間之後。目前沒有技能用。',
  獲得疊層的技能: '使用或擊中時替你累積疊層的技能（連擊、盛怒、飛劍）。',
  條件使用: '要先達成條件才能用的技能：榮耀滿 100、附近有屍體、滑鼠附近有敵人。「近期擊殺」之類也是一種條件。',
  前期消耗: '一次付清的資源消耗，不是每秒消耗。目前所有技能都是前期消耗。',
  重複技能: '可以被重複的技能：用一次就把投射物或效果再放好幾次。目前沒有重複的來源。',
  技能基礎攻擊時間: '出手一次的基礎時間：只看技能的基礎時間與武器每秒攻擊次數，不含攻擊速度提高。只顯示在技能面板。',
  近期: '過去 4 秒內。記錄的事件：擊殺、擊中、暴擊、被擊中。',
