  能量護盾: '先吸收傷害的第二條血，一陣子沒被打會充能。',
  完美閃避: '翻滾剛開始的一瞬間躲過攻擊，時間變慢、下一擊必定暴擊。',
  沉重暈眩:
    '累積滿就暈住敵人。物理、近戰累積更多，冰冷不累積。玩家只有被王的紅光大招打中才累積，暈住 3 秒不能移動、翻滾、格擋、出招。',
  粉碎重擊: '打中沉重暈眩累積到「瀕臨」的敵人時，直接沉重暈眩。',
  禁錮: '不能移動的總稱：冰凍、觸電、沉重暈眩、釘身都算。本身不加傷害，「對禁錮的敵人傷害提高」才吃。',
  釘身: '特定技能與輔助累積，滿了 3 秒不能移動、不能被擊退，觸發時僵直一下；還能出招。結束後釘身的穩固值 +500%，15 秒退回。',
  可釘身: '釘身累積到門檻（普通 40%、魔法 50%、稀有 60%、王 70%）的狀態；目前還沒有技能吃它。',
  目眩: '受到的沉重暈眩累積 +50%，8 秒；不疊加，重上刷新。',
