  碎甲: '只能對完全破甲的敵人施加，存下那一擊 5% 的減免前物理當幅度，5 秒；你之後的攻擊擊中多一筆不吃任何加成的附加物理。完全破甲結束即結束；碎甲的敵人不能再被破甲。',
