  濕透: '更容易被感電（機率 50% 更多）與冰凍（累積 25% 更多），預設 2 秒；不綁任何技能，技能、地面、地圖詞都能施加。',
  超重: '玩家減益：每層緩速 10%，4 秒，重新施加疊層並刷新，最多 5 層。',
