/* 天賦樹的主題（0.2.17，照技能體系重做）：sm 小點（輪流）、nt 大點（名字＋效果）；
   rg 六條路（鬥士、遊俠、暗影、魔導、死靈、自然）各自的權重，叢集照所在方向抽主題；
   inner 防禦與生命（內圈多）、wp 武器專精（只在外圈）；第 0 個「基礎」是過路點（切斷主題，不會被抽到） */
/* 基礎能力點（0.2.7）：數值很低，有點加成又不會沒用 */
