  c_pierce: { n: '元素穿透 +{}%、火焰冰冷閃電抗性 −10%', r: [8, 12], fx: v => ({ pen: v, resA: -10 }) },
  c_bulwark: { n: '格擋機率 +{}%、技能速度 −10%', r: [8, 12], fx: v => ({ block: v, ss: -10 }) }
