  if (['s_hand', 's_buckler', 's_arm', 's_rattan', 's_tiger', 's_crane'].includes(b.id))
    b.aff = [...KINDS.shield.aff, ...PARRY_AFF];
const BASEI = Object.fromEntries(BASES.map(b => [b.id, b]));

/* 詞綴：p 前綴（1）／後綴（0）、r：[T6 的最小, T1 的最大]、add 是「附加 a～b」兩個數 */
